def frequency_sort(s):
    counts = {}
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1
    result = []
    remaining = dict(counts)
    while remaining:
        best_char = max(remaining, key=remaining.get)             # rescans all remaining counts every time
        result.append(best_char * remaining[best_char])
        del remaining[best_char]
    return ''.join(result)


if __name__ == "__main__":
    print(frequency_sort("tree"))

