import java.util.*;

public class Main {
    String frequencySort(String s) {
        Map<Character, Integer> counts = new HashMap<>();
        for (char ch : s.toCharArray()) counts.put(ch, counts.getOrDefault(ch, 0) + 1);
        Map<Character, Integer> remaining = new HashMap<>(counts);
        StringBuilder result = new StringBuilder();
        while (!remaining.isEmpty()) {
            char bestChar = ' ';
            int bestCount = -1;
            for (Map.Entry<Character, Integer> entry : remaining.entrySet()) {   // rescans all remaining counts every time
                if (entry.getValue() > bestCount) {
                    bestCount = entry.getValue();
                    bestChar = entry.getKey();
                }
            }
            for (int i = 0; i < bestCount; i++) result.append(bestChar);
            remaining.remove(bestChar);
        }
        return result.toString();
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.frequencySort("tree"));
    }
}

