public class Main {
    String frequencySort(String s) {
        Map<Character, Integer> counts = new HashMap<>();
        for (char ch : s.toCharArray()) counts.put(ch, counts.getOrDefault(ch, 0) + 1);
        List<List<Character>> buckets = new ArrayList<>();
        for (int i = 0; i <= s.length(); i++) buckets.add(new ArrayList<>());  // one bucket per possible frequency
        for (Map.Entry<Character, Integer> entry : counts.entrySet()) {
            buckets.get(entry.getValue()).add(entry.getKey());
        }
        StringBuilder result = new StringBuilder();
        for (int freq = buckets.size() - 1; freq > 0; freq--) {
            for (char ch : buckets.get(freq)) {
                for (int i = 0; i < freq; i++) result.append(ch);
            }
        }
        return result.toString();
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.frequencySort("tree"));
    }
}

